begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
create function pg_temp.id(n integer)returns uuid language sql immutable as $$select('ae260000-0000-0000-0000-'||lpad(n::text,12,'0'))::uuid$$;
create function pg_temp.claim(n integer)returns text language sql as $$select set_config('request.jwt.claims',jsonb_build_object('sub',pg_temp.id(n),'session_id',pg_temp.id(n+10),'role','authenticated','user_metadata',jsonb_build_object('paid',true,'payment_status','confirmed'))::text,true)$$;
insert into auth.users(id,email,email_confirmed_at)select pg_temp.id(n),'synthetic-reconciliation-'||n||'@example.test',now()from generate_series(1,3)n;
insert into auth.sessions(id,user_id)select pg_temp.id(n+10),pg_temp.id(n)from generate_series(1,3)n;
insert into public.doctor_profiles(user_id,display_name)values(pg_temp.id(1),'Synthetic reconciliation owner');
insert into public.practices(id,owner_user_id,name)values(pg_temp.id(31),pg_temp.id(1),'Synthetic reconciliation clinic');
insert into public.memberships(id,practice_id,user_id,capabilities)values(pg_temp.id(32),pg_temp.id(31),pg_temp.id(3),array['patients.read']);
insert into public.doctor_saas_terms_versions(id,plan_key,version,status,currency,currency_exponent,monthly_minor,trial_days,staff_limit,staff_unlimited,clinic_limit,clinic_unlimited,over_limit_policy,renewal_policy,grace_days,expiry_policy,cancellation_policy,refund_policy,terms_document_ref,commercial_approval_ref,legal_approval_ref)values
 (pg_temp.id(51),'synthetic-reconciliation',1,'approved','USD',2,9007199254740991,2,1,false,1,false,'block_new_allocation','manual',0,'historical_read_only','period_end','manual_review','synthetic-reconciliation/v1','SYNTHETIC_COMMERCIAL','SYNTHETIC_LEGAL'),
 (pg_temp.id(52),'synthetic-reconciliation',2,'approved','JPY',0,97,2,1,false,1,false,'block_new_allocation','manual',0,'historical_read_only','period_end','manual_review','synthetic-reconciliation/v2','SYNTHETIC_COMMERCIAL','SYNTHETIC_LEGAL');
insert into public.doctor_saas_terms_documents(terms_version_id,document_ref,content_en,content_ar)values
 (pg_temp.id(51),'synthetic-reconciliation/v1','Synthetic reconciliation document; not merchant acceptance.','وثيقة اختبار اصطناعية فقط دون موافقة قانونية.'),
 (pg_temp.id(52),'synthetic-reconciliation/v2','Synthetic second reconciliation document; not merchant acceptance.','وثيقة اختبار اصطناعية فقط دون موافقة قانونية.');
update public.doctor_saas_configuration set terms_version_id=pg_temp.id(51),revision=revision+1,change_reason='Owned synthetic reconciliation';
create temporary table results(n integer primary key,quote jsonb,intent jsonb);grant all on results to authenticated;
set local role authenticated;select pg_temp.claim(1);
insert into results(n,quote)select n,public.doctor_create_saas_quote(pg_temp.id(51),2,0,'monthly','synthetic-reconciliation/v1',pg_temp.id(n+60))from generate_series(1,2)n;
update results set intent=public.doctor_prepare_saas_payment((quote->>'quote_id')::uuid,pg_temp.id(n+70));
select is(public.doctor_saas_financial_status()->>'total','2','owner report counts full own population');
select is(public.doctor_saas_financial_status(0,1)#>>'{currencies,0,quoted_minor}','18014398509481982','aggregate minor units remain exact above JavaScript safe integer');
select is(jsonb_array_length(public.doctor_saas_financial_status(0,1)->'items'),1,'page size limits rows but never total');
reset role;
create function pg_temp.evidence(n integer,event text,sequence integer,outcome text,subscriber integer,amount bigint,currency text,delivery integer)returns jsonb language sql as $$select doctor_private.record_saas_synthetic_evidence((select intent->>'intent_id'from results where results.n=$1)::uuid,event,sequence,outcome,pg_temp.id(subscriber),amount,currency,pg_temp.id(delivery))$$;
select is(pg_temp.evidence(1,'synthetic-fixture/one',2,'confirmed',1,9007199254740991,'USD',81)->>'binding','matching','exact synthetic amount/currency/subscriber matches bound intent');
select is(doctor_private.saas_synthetic_reconciliation((select intent->>'intent_id'from results where n=1)::uuid),'confirmed_synthetic','synthetic confirmation stays explicitly synthetic');
select is(pg_temp.evidence(1,'synthetic-fixture/one',2,'confirmed',1,9007199254740991,'USD',81)->>'disposition','recorded','exact delivery retry returns immutable receipt');
select is(pg_temp.evidence(1,'synthetic-fixture/one',2,'confirmed',1,9007199254740991,'USD',82)->>'disposition','duplicate','duplicate callback identity retained as duplicate delivery');
select is(pg_temp.evidence(1,'synthetic-fixture/older',1,'pending',1,9007199254740991,'USD',83)->>'disposition','recorded','out-of-order pending evidence persists');
select is(doctor_private.saas_synthetic_reconciliation((select intent->>'intent_id'from results where n=1)::uuid),'confirmed_synthetic','late pending cannot downgrade confirmed evidence');
select is((select count(*)from public.doctor_saas_synthetic_events),2::bigint,'duplicate events allocate once');
select is((select count(*)from public.doctor_saas_synthetic_deliveries),3::bigint,'delivery retries are exact; new duplicate/out-of-order deliveries persist');
select throws_ok($$select pg_temp.evidence(1,'synthetic-fixture/one',2,'confirmed',1,1,'USD',81)$$,'22023','DOCTOR_IDEMPOTENCY_CONFLICT','delivery retry cannot change money');
select is(pg_temp.evidence(1,'synthetic-fixture/one',2,'confirmed',1,1,'USD',84)->>'disposition','conflict','conflicting provider event identity is audited rather than overwritten');
select is(doctor_private.saas_synthetic_reconciliation((select intent->>'intent_id'from results where n=1)::uuid),'discrepancy_review','changed event payload requires review');
select is(pg_temp.evidence(2,'synthetic-fixture/mismatch',1,'confirmed',2,1,'JPY',85)->>'binding','mismatch','wrong amount currency and subscriber cannot match');
select is(doctor_private.saas_synthetic_reconciliation((select intent->>'intent_id'from results where n=2)::uuid),'discrepancy_review','mismatched confirmation never settles');
select throws_ok($$select pg_temp.evidence(2,'live-provider/claim',1,'confirmed',1,9007199254740991,'USD',86)$$,'22023','DOCTOR_SAAS_SYNTHETIC_EVIDENCE_INVALID','fixture interface cannot claim live provider evidence');
select throws_ok($$select pg_temp.evidence(2,'synthetic-fixture/claim',1,'refunded',1,9007199254740991,'USD',86)$$,'22023','DOCTOR_SAAS_SYNTHETIC_EVIDENCE_INVALID','refunds are not invented or automatically issued');
update public.doctor_saas_configuration set terms_version_id=pg_temp.id(52),revision=revision+1,change_reason='Owned synthetic separate currency';
set local role authenticated;select pg_temp.claim(1);
insert into results(n,quote)values(3,public.doctor_create_saas_quote(pg_temp.id(52),3,0,'monthly','synthetic-reconciliation/v2',pg_temp.id(63)));
update results set intent=public.doctor_prepare_saas_payment((quote->>'quote_id')::uuid,pg_temp.id(73))where n=3;
select is(jsonb_array_length(public.doctor_saas_financial_status()->'currencies'),2,'currencies and explicit exponents stay separated');
select is(public.doctor_saas_financial_status()->>'total','3','pagination-independent totals retain original intent source links');
select is(public.doctor_saas_financial_status()->>'scope','saas_only','scope is exclusively SaaS');
select is(public.doctor_saas_financial_status()->>'patient_revenue_included','false','patient revenue excluded');
select is(public.doctor_saas_financial_status()->>'settlement_available','false','synthetic confirmed evidence never enables settlement');
select is(public.doctor_saas_financial_status()->>'invoices_available','false','no tax applicability or invoice semantics invented');
select is(public.doctor_saas_financial_status()->>'lifecycle_available','false','commercial lifecycle cannot execute without approved route/policy');
select is(public.doctor_saas_financial_status()->>'independent_financial_review','pending','no self-issued financial review');
select is(public.doctor_saas_financial_status()->>'paid_activation_available','false','report is never paid authority');
select is(public.doctor_saas_financial_status()->>'live_activation','false','report cannot activate live edition');
select ok(exists(select 1 from jsonb_array_elements(public.doctor_saas_financial_status()->'items')i where jsonb_array_length(i->'synthetic_event_ids')>0),'report links to immutable synthetic event IDs');
select pg_temp.claim(2);
select is(public.doctor_saas_financial_status()->>'total','0','foreign owner sees no other subscriber totals');
select is(public.doctor_saas_financial_status()->'items','[]'::jsonb,'foreign owner sees no source links');
select pg_temp.claim(3);
select throws_ok($$select public.doctor_saas_financial_status()$$,'42501','DOCTOR_OWNER_ENROLLMENT_REQUIRED','delegated readers cannot aggregate another subscriber finances');
reset role;
select is(pg_temp.evidence(3,'synthetic-fixture/unknown',3,'unknown',1,97,'JPY',87)->>'settled','false','unknown outcome has no paid side effect');
select is(doctor_private.saas_synthetic_reconciliation((select intent->>'intent_id'from results where n=3)::uuid),'unknown_review','unknown remains review-required');
select is(pg_temp.evidence(3,'synthetic-fixture/confirmed',4,'confirmed',1,97,'JPY',88)->>'settled','false','even matching confirmed fixture never settles actual money');
select is(doctor_private.saas_synthetic_reconciliation((select intent->>'intent_id'from results where n=3)::uuid),'confirmed_synthetic','exact later confirmation reconciles unknown fixture');
select is(pg_temp.evidence(3,'synthetic-fixture/failed',2,'failed',1,97,'JPY',89)->>'settled','false','failed fixture never changes access');
select is(doctor_private.saas_synthetic_reconciliation((select intent->>'intent_id'from results where n=3)::uuid),'discrepancy_review','contradictory terminal evidence cannot be silently applied');
select is((select count(*)from public.doctor_saas_accounts),0::bigint,'no subscription account created by financial evidence');
select is((select count(*)from public.doctor_saas_periods),0::bigint,'no paid or trial period allocated by evidence');
select ok((select bool_and(state='awaiting_route_approval')from public.doctor_saas_payment_intents),'all intents remain held regardless of evidence');
select throws_ok($$update public.doctor_saas_synthetic_events set outcome='confirmed'$$,'42501','DOCTOR_SAAS_HISTORY_IMMUTABLE','evidence history immutable');
select throws_ok($$truncate public.doctor_saas_synthetic_deliveries$$,'42501','DOCTOR_SAAS_HISTORY_IMMUTABLE','delivery history immutable');
select ok(not has_table_privilege(role_name,'public.'||table_name,'select,insert,update,delete,truncate'),'raw '||role_name||' access denied: '||table_name)
 from unnest(array['anon','authenticated','service_role'])role_name cross join unnest(array['doctor_saas_synthetic_events','doctor_saas_synthetic_deliveries'])table_name;
select ok(not has_function_privilege(role_name,'doctor_private.record_saas_synthetic_evidence(uuid,text,bigint,text,uuid,bigint,text,uuid)','execute'),'no fixture-ingest grant for '||role_name)from unnest(array['anon','authenticated','service_role'])role_name;
select ok(not has_function_privilege(role_name,'public.doctor_saas_financial_status(integer,integer)','execute'),'no financial RPC execution for '||role_name)from unnest(array['anon','service_role'])role_name;
select * from finish();rollback;
